import subprocess, re, collections, os

branches=['rachel','monica','phoebe','joey','chandler','ross']
records=[]
for name in branches:
    branch=f'friend/{name}'
    out=subprocess.check_output(['git','log','--reverse','--format=%H%x1f%aI', f'origin/{branch}'], text=True)
    for line in out.splitlines():
        sha, ts = line.split('\x1f')
        body=subprocess.check_output(['git','show','-s','--format=%B', sha], text=True)
        if not re.search(r'^Friend-Message: 1$', body, re.M):
            continue
        m_ep=re.search(r'^Episode: (.*)$', body, re.M)
        if not m_ep: 
            continue
        records.append((sha,m_ep.group(1).strip()))

# existing SHAs by episode file
existing_by_ep=collections.defaultdict(set)
for root,_,files in os.walk('.'):
    for f in files:
        if re.fullmatch(r'E\d+\.md', f) and os.path.basename(root).startswith('S'):
            path=os.path.join(root,f)
            ep=os.path.join(os.path.basename(root),f).replace('.md','')  # S01/E01
            # normalize slash
            ep=f"{os.path.basename(root)}/{f.replace('.md','')}"
            txt=open(path).read()
            for sha in re.findall(r'Source: friend/\w+ @ ([0-9a-f]+)', txt):
                existing_by_ep[ep].add(sha)

missing_by_ep=collections.Counter()
for sha,ep in records:
    if sha not in existing_by_ep.get(ep,set()):
        missing_by_ep[ep]+=1
for ep in sorted(missing_by_ep):
    print(ep, missing_by_ep[ep])
print("total missing", sum(missing_by_ep.values()))
